<?php
declare(strict_types=1);
final class LifePlanningReports {
 public static function metal(array $holding):?array{$unit=['g'=>1,'pavan'=>8,'troy_oz'=>31.1034768];if(!isset($unit[$holding['unit']])||$holding['purity']===null)return null;$price=null;foreach(LifePlanningService::rows('prices')as $p)if($p['priced_on']<=date('Y-m-d')&&($p['kind']===$holding['kind']||$holding['kind']==='jewellery'&&$p['kind']==='gold')&&(!$price||$p['priced_on']>$price['priced_on']))$price=$p;if(!$price||!isset($unit[$price['unit']])||$price['purity']<=0)return null;$purity=$holding['purity_unit']==='karat'?$holding['purity']/24:$holding['purity']/100;$value=$holding['weight']*$unit[$holding['unit']]*$purity/($price['purity']/100)*$price['price_per_unit']/$unit[$price['unit']];return ['value'=>round($value,2),'as_of'=>$price['priced_on'],'source'=>$price['source']];}
 public static function seettu(array $circle):array{$today=new DateTimeImmutable('today');$date=new DateTimeImmutable($circle['start_on']);$due=0;for($i=0;$i<$circle['rounds'];$i++){if($date<=$today)$due++;if($circle['frequency']==='weekly')$date=$date->modify('+7 days');else{$next=$date->modify('first day of next month');$date=$next->setDate((int)$next->format('Y'),(int)$next->format('m'),min((int)substr($circle['start_on'],8,2),(int)$next->format('t')));}}$paid=0;foreach(LifePlanningService::rows('seettu_payments')as $p)if($p['seettu_id']===$circle['id']&&$p['status']==='paid'&&$p['round_no']<=$due)$paid+=$p['amount'];return ['rounds_due'=>$due,'expected'=>$due*$circle['contribution'],'paid'=>$paid,'arrears'=>max(0,round($due*$circle['contribution']-$paid,2))];}
 public static function birthdays():array{$out=[];$today=date('Y-m-d');$soon=date('Y-m-d',strtotime('+7 days'));foreach(LifePlanningService::rows('contacts')as $r)if($r['birthday']){$md=substr($r['birthday'],5);$next=date('Y').'-'.$md;$d=DateTimeImmutable::createFromFormat('!Y-m-d',$next);if($d->format('Y-m-d')<$today)$d=DateTimeImmutable::createFromFormat('!Y-m-d',((int)date('Y')+1).'-'.$md);$next=$d->format('Y-m-d');if($next<=$soon)$out[]=['id'=>$r['id'],'name'=>$r['name'],'date'=>$next];}return $out;}
 public static function alerts():array{$out=[];$today=date('Y-m-d');$soon=date('Y-m-d',strtotime('+7 days'));$add=function($id,$title,$body,$page)use(&$out,$today){$out[]=['id'=>hash('sha256','life-extended:'.$id.':'.$today),'title'=>$title,'body'=>$body,'route'=>'/life?page='.$page,'level'=>'upcoming'];};foreach(LifePlanningService::rows('vehicles')as $r)foreach(['insurance_expiry','licence_expiry','emission_expiry']as $field)if($r[$field]&&$r[$field]<=$soon)$add('vehicle'.$r['id'].$field,'Vehicle renewal',$r['name'].' · '.str_replace('_',' ',$field).' · '.$r[$field],'vehicles');foreach(self::birthdays()as $b)$add('birthday'.$b['id'],'Birthday coming up',$b['name'].' · '.$b['date'],'contacts');foreach(LifePlanningService::rows('contacts')as $c)if($c['next_followup']&&$c['next_followup']<=$today)$add('contact'.$c['id'],'People follow-up',$c['name'].' · '.$c['next_followup'],'contacts');return $out;}
}
